import { useEffect, useRef } from 'react';
import './About.css';

export default function About() {
  const ref = useRef(null);

  //new style

  useEffect(() => {
    const wrap = document.getElementById('lanyardWrap');
    if (!wrap) return;
    let rot = 0, vel = 0, raf;
    let isHovered = false;

    const onMove = e => {
      if (!isHovered) return;
      const r = wrap.getBoundingClientRect();
      const cx = r.left + r.width / 2;
      const dx = (e.clientX - cx) / 100;
      vel += dx * 1.2;
    };

    const onEnter = () => { isHovered = true; };
    const onLeave = () => { isHovered = false; };

    const physics = () => {
      vel *= 0.88;
      rot += vel;
      rot *= 0.80;
      wrap.style.transform = `rotate(${rot}deg) translateY(${Math.abs(rot) * 4}px)`;
      raf = requestAnimationFrame(physics);
    };

    wrap.addEventListener('mousemove', onMove);
    wrap.addEventListener('mouseenter', onEnter);
    wrap.addEventListener('mouseleave', onLeave);
    raf = requestAnimationFrame(physics);

    return () => {
      wrap.removeEventListener('mousemove', onMove);
      wrap.removeEventListener('mouseenter', onEnter);
      wrap.removeEventListener('mouseleave', onLeave);
      cancelAnimationFrame(raf);
    };
  }, []);

  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { ref.current?.classList.add('on'); obs.disconnect(); } },
      { threshold: 0.15 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section id="about" className="section reveal" ref={ref}>
      <div className="sec-label">01 — About</div>
      <h2 className="sec-title">Who I Am</h2>

      <div className="about-grid">
        {/* Image side */}
        <div className="iwrap">
          <div className="lanyard-wrap" id="lanyardWrap">
            <div className="lanyard-rope">
              <div className="rope-line" />
            </div>
            <div className="id-card" id="idCard">
              <div className="card-hole">
                <div className="rope-through" />
              </div>
              <div className="card-img">
                <img src="/images/my pic.jpeg" alt="M Ahmad" onError={e => e.target.style.display = 'none'} />
              </div>
              <div className="card-info">
                <span className="card-name">M Ahmad</span>
                <span className="card-role">Full Stack Dev</span>
                <div className="card-badge">
                  <span className="card-dot" />
                  Open to Work
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Text side */}
        <div className="about-text">
          <p className="about-hi">Junior Full Stack Developer</p>

          <p className="about-bio">
            Hey! I'm <strong>M Ahmad</strong> — a passionate <strong>Junior Full Stack Developer</strong> who
            recently started my journey in web development. I may be a fresher, but I bring
            <strong> strong dedication, curiosity</strong>, and a love for building things that work beautifully.
          </p>

          <p className="about-bio" style={{ marginTop: '16px' }}>
            On the <strong>frontend</strong>, I work with HTML, CSS, JavaScript, and React to build clean,
            responsive interfaces. I'm actively learning the <strong>backend</strong> side —
            Node.js, Express &amp; MongoDB — to grow into a complete full-stack developer.
          </p>

          <p className="about-bio" style={{ marginTop: '16px' }}>
            I believe every expert was once a beginner. I'm here to <strong>learn fast, build real things</strong>,
            and grow with every project I touch. 🚀
          </p>

          <div className="about-tags">
            <span className="tag">🎓 Fresh Graduate</span>
            <span className="tag">⚡ Fast Learner</span>
            <span className="tag">💡 Problem Solver</span>
            <span className="tag">🌐 Open to Work</span>
          </div>
        </div>
      </div>
    </section>
  );
}
